def tax():
 url='https://legislatie.just.ro/Public/DetaliiDocumentAfis/300022';raw=urllib.request.urlopen(urllib.request.Request(url,headers={'User-Agent':'Mozilla/5.0'}),timeout=12).read();text=' '.join(html.fromstring(raw).text_content().split());assert '21%' in text and '1 august 2025' in text
 pdf=r/'A03/ANAF_cote_TVA_2025_09.pdf'; D=decimal.Decimal
 def calc(g,rate):
  gross=D(g);rr=D(rate);net=(gross/(D(1)+rr)).quantize(D('.01'),rounding=decimal.ROUND_HALF_UP);return {'gross':str(gross),'rate':str(rr),'net':str(net),'vat':str(gross-net)}
 put('tva_oracol.json',{'utc':now(),'law':{'url':url,'page_sha256':hashlib.sha256(raw).hexdigest(),'title':'Legea nr. 141 din 25 iulie 2025','selector':'art. II, modificarea Codului fiscal art.291 alin.(1); art. VII alin.(1), intrare în vigoare','locator':text[max(0,text.find('La articolul 291, alineatele (1) și (2)')-8):text.find('La articolul 291, alineatele (1) și (2)')+72],'period_fact':'2025-09-15','rule':'Operațiune internă taxabilă în România, neexceptată și nesupusă cotei reduse, la data de referință. Cota standard 21%. Nu se extinde la alte regimuri, jurisdicții sau date fără verificare.'},'ANAF':{'url':'https://static.anaf.ro/static/10/Anaf/AsistentaContribuabili_r/Cotele_de_TVA_09.2025.pdf','sha256':digest(pdf)},'gross_cases':[calc('12.50','.19'),calc('12.50','.21'),calc('87.50','.19'),calc('87.50','.21')],'net_example':{'net':'12.50','rate':'0.21','vat':'2.63','gross':'15.13','rounding':'fixture: HALF_UP pe suma taxei, 2 zecimale. Checkout-ul testat folosește preț brut. Exemplul net este un martor, nu o comandă executată.'},'checkout_artifacts':['Checkout_probe.json','A11_reproduceri_lot1/A03_checkout_replay.json','Provenienta_API_web.json'],'limit':'Fixture checkout nu include dovada că un produs comercial real anume se încadrează în standard și nu probează factura emisă; analiza legală fixează explicit data economică.'})
def bench():
 q="""WITH facts AS (SELECT 11 AS ad_client_id,(n % 60) acct,CASE WHEN n % 2 = 0 THEN 101 ELSE 200000 END schema_id, 'A'::text postingtype,date '2026-01-01'+(n % 280)::int dateacct,CASE WHEN n%3=0 THEN 0 ELSE (n % 1000)::numeric/100 END dr, CASE WHEN n%3=0 THEN (n % 1000)::numeric/100 ELSE 0 END cr FROM generate_series(1,%s) s(n)) SELECT schema_id,acct,count(*) n,sum(dr) dr,sum(cr) cr FROM facts WHERE ad_client_id=11 AND postingtype='A' AND dateacct<=date '2026-12-31' GROUP BY schema_id,acct ORDER BY 1,2"""
 def run(vol):
  with psycopg.connect(host='127.0.0.1',port=56481,dbname='p01_garden',user='audit_owner',options='-c default_transaction_read_only=on -c statement_timeout=12000') as db:
   start=time.perf_counter();z=db.execute(q.replace('%','%%').replace('%%s','%s'),(vol,)).fetchall(); return {'size':vol,'seconds':round(time.perf_counter()-start,5),'output_rows':len(z),'accounted_input':sum(int(x[2]) for x in z),'hash':hashlib.sha256(repr(z).encode()).hexdigest()}
 sets={}
 for workers,vol,n in [(1,100000,5),(2,100000,4),(5,100000,5),(1,1000000,2)]:
  with cf.ThreadPoolExecutor(max_workers=workers) as p:sets[f'{workers} sessions {vol} facts']=list(p.map(run,[vol]*n))
 put('performance_sql.json',{'utc':now(),'engine':'PostgreSQL16 localhost GardenWorld, transactions read-only; synthetic rows from generate_series','query':q,'runs':sets,'limit':'Coût SQL de regroupement sur données synthétiques, sans DML et sans table physique. Ne constitue pas un p95 UI, export PDF, mesure de plan sur index de Fact_Acct, premier accès froid, ni une certification du SLA.','expectation':'counted input equals requested 100000 or1000000 and hashes repeat for equal cardinality.'})
if __name__=='__main__': {'pg':database,'precision':amounts,'tax':tax,'bench':bench}[sys.argv[1]]()
